@pragma('vm:entry-point')
String stringXor(String a, String b) {
  String xor(String i, String j) {
    if (i == j) {
      return '0';
    } else {
      return '1';
    }
  }

  List<String> result = [];
  for (int i = 0; i < a.length; i++) {
    result.add(xor(a[i], b[i]));
  }
  return result.join('');
