bool triplesSumToZero(List<int> l) {
  for (int i = 0; i < l.length; i++) {
    for (int j = i + 1; j < l.length; j++) {
      for (int k = j + 1; k < l.length; k++) {
        if (l[i] + l[j] + l[k] == 0) {
          return true;
        }
      }
    }
  }
  return false;
}

