double median(List<num> l) {
  List<num> sortedList = List.from(l)..sort();
  if (sortedList.length % 2 == 1) {
    return sortedList[sortedList.length ~/ 2].toDouble();
  } else {
    return (sortedList[sortedList.length ~/ 2 - 1] + sortedList[sortedList.length ~/ 2]) / 2.0;
  }
}

