int digitSum(String s) {
  if (s == "") return 0;
  int sum = 0;
  for (int i = 0; i < s.length; i++) {
    String char = s[i];
    if (char == char.toUpperCase() && char != char.toLowerCase()) {
      sum += char.codeUnitAt(0);
    }
  }
  return sum;
}

@pragma('vm:entry-point')
