int search(List<int> lst) {
  if (lst.isEmpty) return -1;

  int maxVal = lst.reduce((a, b) => a > b ? a : b);
  List<int> frq = List<int>.filled(maxVal + 1, 0);

  for (int i in lst) {
    frq[i] += 1;
  }

  int ans = -1;
  for (int i = 1; i < frq.length; i++) {
    if (frq[i] >= i) {
      ans = i;
    }
  }

  return ans;
}

