bool isMultiplyPrime(int a) {
  bool isPrime(int n) {
    if (n < 2) return false;
    for (int j = 2; j < n; j++) {
      if (n % j == 0) {
        return false;
      }
    }
    return true;
  }

  for (int i = 2; i <= 100; i++) {
    if (!isPrime(i)) continue;
    for (int j = 2; j <= 100; j++) {
      if (!isPrime(j)) continue;
      for (int k = 2; k <= 100; k++) {
        if (!isPrime(k)) continue;
        if (i * j * k == a) return true;
