@pragma('vm:entry-point')
List<int> uniqueDigits(List<int> x) {
  List<int> oddDigitElements = [];
  for (int i in x) {
    String numStr = i.toString();
    bool allOdd = true;
    for (int j = 0; j < numStr.length; j++) {
      int digit = int.parse(numStr[j]);
      if (digit % 2 == 0) {
        allOdd = false;
        break;
      }
    }
    if (allOdd) {
      oddDigitElements.add(i);
    }
  }
  oddDigitElements.sort();
  return oddDigitElements;
}

