@pragma('vm:entry-point')
List<int> evenOddPalindrome(int n) {
  bool isPalindrome(int num) {
    String str = num.toString();
    String reversed = str.split('').reversed.join('');
    return str == reversed;
  }

  int evenPalindromeCount = 0;
  int oddPalindromeCount = 0;

  for (int i = 1; i <= n; i++) {
    if (i % 2 == 1 && isPalindrome(i)) {
      oddPalindromeCount += 1;
    } else if (i % 2 == 0 && isPalindrome(i)) {
      evenPalindromeCount += 1;
    }
  }

  return [evenPalindromeCount, oddPalindromeCount];
}

@pragma('vm:entry-point')
void main() {
  // Test case 1
  List<int> result1 = evenOddPalindrome(3);
  print(result1); // [1, 2]

  // Test case 2
  List<int> result2 = evenOddPalindrome(12);
  print(result2); // [4, 6]

  // Additional test cases
  List<int> result3 = evenOddPalindrome(1);
  print(result3); // [0, 1]

  List<int> result4 = evenOddPalindrome(100);
  print(result4); // [9, 9]
}

