@pragma('vm:entry-point')
int countNums(List<int> arr) {
  @pragma('vm:entry-point')
  int digitsSum(int n) {
    int neg = 1;
    if (n < 0) {
      n = -1 * n;
      neg = -1;
    }
    List<int> digits = n.toString().split('').map((i) => int.parse(i)).toList();
    digits[0] = digits[0] * neg;
    return digits.reduce((a, b) => a + b);
  }

  return arr.map((i) => digitsSum(i)).where((x) => x > 0).length;
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  assert(countNums([]) == 0);
  assert(countNums([-1, 11, -11]) == 1);
  assert(countNums([1, 1, 2]) == 3);

  print('All tests passed!');
}

