bool moveOneBall(List<int> arr) {
  if (arr.isEmpty) {
    return true;
  }

  List<int> sortedArray = List.from(arr)..sort();
  List<int> myArr = [];

  int minValue = arr.reduce((a, b) => a < b ? a : b);
  int minIndex = arr.indexOf(minValue);
  myArr = arr.sublist(minIndex) + arr.sublist(0, minIndex);

  for (int i = 0; i < arr.length; i++) {
    if (myArr[i] != sortedArray[i]) {
      return false;
    }
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  print(moveOneBall([3, 4, 5, 1, 2]));
  print(moveOneBall([3, 5, 4, 1, 2]));
  print(moveOneBall([]));
  print(moveOneBall([1, 2, 3, 4, 5]));
  print(moveOneBall([5, 1, 2, 3, 4]));
}

