@pragma('vm:entry-point')
int minSubArraySum(List<int> nums) {
  int maxSum = 0;
  int s = 0;
  for (int num in nums) {
    s += -num;
    if (s < 0) {
      s = 0;
    }
    maxSum = s > maxSum ? s : maxSum;
  }
  if (maxSum == 0) {
    maxSum = nums.map((i) => -i).reduce((a, b) => a > b ? a : b);
  }
  int minSum = -maxSum;
  return minSum;
}

