int maxFill(List<List<int>> grid, int capacity) {
  int totalLowers = 0;
  for (List<int> row in grid) {
    int waterUnits = row.reduce((a, b) => a + b);
    totalLowers += (waterUnits / capacity).ceil();
  }
  return totalLowers;
}

