@pragma('vm:entry-point')
String fixSpaces(String text) {
  String newText = "";
  int i = 0;
  int start = 0;
  int end = 0;

  while (i < text.length) {
    if (text[i] == " ") {
      end += 1;
    } else {
      if (end - start > 2) {
        newText += "-" + text[i];
      } else if (end - start > 0) {
        newText += "_" * (end - start) + text[i];
      } else {
        newText += text[i];
      }
      start = i + 1;
      end = i + 1;
    }
    i += 1;
  }

  if (end - start > 2) {
    newText += "-";
  } else if (end - start > 0) {
    newText += "_";
  }

  return newText;
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  assert(fixSpaces("Example") == "Example");
  assert(fixSpaces("Example 1") == "Example_1");
  assert(fixSpaces(" Example 2") == "_Example_2");
  assert(fixSpaces(" Example   3") == "_Example-3");

  print("All tests passed!");
}

tests:
