int digitsSum(int n) {
  int neg = 1;
  if (n < 0) {
    n = -1 * n;
    neg = -1;
  }
  List<int> digits = n.toString().split('').map((i) => int.parse(i)).toList();
  digits[0] = digits[0] * neg;
  return digits.reduce((a, b) => a + b);
}

@pragma('vm:entry-point')
List<int> orderByPoints(List<int> nums) {
  List<MapEntry<int, int>> indexed = [];
  for (int i = 0; i < nums.length; i++) {
    indexed.add(MapEntry(i, nums[i]));
  }

  indexed.sort((a, b) {
    int sumA = digitsSum(a.value);
    int sumB = digitsSum(b.value);
    if (sumA != sumB) {
      return sumA.compareTo(sumB);
    }
    return a.key.compareTo(b.key);
  });

  return indexed.map((e) => e.value).toList();
}

